115	/// Dispatches spec round-trip rewriting to the appropriate ecosystem handler.
116	pub fn round_trip(ecosystem: Ecosystem, spec: &DepSpec, target: &Version) -> Option<DepSpec> {
117	    match (ecosystem, spec) {
118	        #[cfg(feature = "cargo")]
119	        (Ecosystem::Cargo, _) => cargo::round_trip(spec, target),
120	        #[cfg(feature = "npm")]
121	        (Ecosystem::Npm, _) => npm::round_trip(spec, target),
122	        _ => None,
123	    }
124	}
