1	use callisto_model::{CommandRunner, ValidateReport, SCHEMA_VERSION};
2	
3	use crate::commands::escalate;
4	use crate::error::GraphError;
5	use crate::resolver::DependencyResolver;
6	use crate::Workspace;
7	
8	#[derive(Clone, Debug, Default)]
9	pub struct ValidateOptions {
10	    pub staged: bool,
11	    pub since: Option<String>,
12	    pub strict: bool,
13	    pub strict_graph: bool,
14	}
15	
16	pub fn validate<R: CommandRunner, D: DependencyResolver>(
17	    ws: &Workspace<'_, R, D>,
18	    opts: &ValidateOptions,
19	) -> Result<ValidateReport, GraphError> {
20	    let mut diagnostics = Vec::new();
21	    let loaded = crate::load_changesets(&ws.root, &ws.config)?;
22	
23	    let target_changesets: Vec<_> = if opts.staged {
24	        let out = ws
25	            .runner
26	            .run("git", &["diff", "--cached", "--name-only"], &ws.root)?;
27	        if !out.success() {
28	            return Err(GraphError::Command(callisto_model::CommandError::Io {
29	                program: "git".to_string(),
30	                message: out.stderr,
31	            }));
32	        }
33	        let files: Vec<String> = out
34	            .stdout_trimmed()
35	            .lines()
36	            .map(|l| l.trim_matches('"').to_string())
37	            .collect();
38	        loaded
39	            .into_iter()
40	            .filter(|cs| files.iter().any(|f| cs.path.ends_with(f)))
41	            .collect()
42	    } else if let Some(ref since) = opts.since {
43	        if since.starts_with('-') {
44	            return Err(GraphError::Command(callisto_model::CommandError::Io {
45	                program: "git".to_string(),
46	                message: "invalid since ref".to_string(),
47	            }));
48	        }
49	        let range = format!("{since}..HEAD");
50	        let out = ws
51	            .runner
52	            .run("git", &["diff", "--name-only", &range, "--"], &ws.root)?;
53	        if !out.success() {
54	            return Err(GraphError::Command(callisto_model::CommandError::Io {
55	                program: "git".to_string(),
56	                message: out.stderr,
57	            }));
58	        }
59	        let files: Vec<String> = out
60	            .stdout_trimmed()
61	            .lines()
62	            .map(|l| l.trim_matches('"').to_string())
63	            .collect();
64	        loaded
65	            .into_iter()
66	            .filter(|cs| files.iter().any(|f| cs.path.ends_with(f)))
67	            .collect()
68	    } else {
69	        loaded
70	    };
71	
72	    for cs in &target_changesets {
73	        if cs.changeset.entries.is_empty() {
74	            diagnostics.push(callisto_model::Diagnostic {
75	                code: callisto_model::DiagnosticCode::EmptyChangeset,
76	                severity: callisto_model::DiagnosticSeverity::Error,
77	                message: format!("Changeset `{}` is empty", cs.path.display()),
78	                package: None,
79	                path: Some(cs.path.clone()),
80	                governed_by: None,
81	                escalated_by: None,
82	            });
83	        }
84	
85	        for entry in &cs.changeset.entries {
86	            if let Ok(id) = callisto_model::PackageId::parse(&entry.name) {
87	                if !ws.graph.packages().any(|p| p.id.matches(&id)) {
88	                    diagnostics.push(callisto_model::Diagnostic {
89	                        code: callisto_model::DiagnosticCode::UnknownPackage,
90	                        severity: callisto_model::DiagnosticSeverity::Error,
91	                        message: format!(
92	                            "Changeset `{}` references unknown package `{}`",
93	                            cs.path.display(),
94	                            entry.name
95	                        ),
96	                        package: Some(id),
97	                        path: Some(cs.path.clone()),
98	                        governed_by: None,
99	                        escalated_by: None,
100	                    });
101	                }
102	            }
103	        }
104	    }
105	
106	    escalate(&mut diagnostics, opts.strict, opts.strict_graph);
107	
108	    let is_valid = diagnostics
109	        .iter()
110	        .all(|d| d.severity != callisto_model::DiagnosticSeverity::Error);
111	    Ok(ValidateReport {
112	        schema_version: SCHEMA_VERSION,
113	        valid: is_valid,
114	        diagnostics,
115	    })
116	}
