1	use callisto_model::{
2	    CommandRunner, CratePublish, NpmMainPublish, PublishPlan, PublishTarget, ReleaseEntry,
3	    SCHEMA_VERSION,
4	};
5	
6	use crate::error::GraphError;
7	use crate::resolver::{DependencyResolver, DependencyResolverExt};
8	use crate::Workspace;
9	
10	#[derive(Clone, Debug, Default)]
11	pub struct PublishOptions {}
12	
13	pub fn plan_publish<R: CommandRunner, D: DependencyResolver>(
14	    ws: &Workspace<'_, R, D>,
15	    _opts: &PublishOptions,
16	) -> Result<PublishPlan, GraphError> {
17	    let mut rust_crates = Vec::new();
18	    let mut npm_main_packages = Vec::new();
19	    let mut npm_platform_packages = Vec::new();
20	    let mut releases = Vec::new();
21	
22	    let base_versions = ws.base_versions()?;
23	    let inference = crate::infer::NoInference;
24	    let version_plan = crate::commands::version::plan_version(
25	        ws,
26	        &inference,
27	        &crate::commands::version::VersionOptions::default(),
28	    )
29	    .ok();
30	
31	    let all_ids: std::collections::HashSet<_> = ws.graph.packages().map(|p| p.id.clone()).collect();
32	    let topo_ids = ws.graph.toposort(&all_ids)?;
33	
34	    let head_sha = if let Ok(repo) = callisto_vcs::GitRepository::discover(&ws.root) {
35	        repo.head_sha().ok()
36	    } else {
37	        None
38	    };
39	
40	    for id in &topo_ids {
41	        let pkg = match ws.graph.packages().find(|p| &p.id == id) {
42	            Some(p) => p,
43	            None => continue,
44	        };
45	
46	        let bump_info = version_plan
47	            .as_ref()
48	            .and_then(|plan| plan.bumps.iter().find(|b| b.package == pkg.id));
49	
50	        let (is_release, ver) = if let Some(bump) = bump_info {
51	            (true, bump.to.clone())
52	        } else {
53	            let cur_ver = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
54	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
55	                    path: pkg
56	                        .manifests
57	                        .first()
58	                        .map(|m| m.path.clone())
59	                        .unwrap_or_default(),
60	                    field: "version",
61	                })
62	            })?;
63	            let tag_match = ws
64	                .tags
65	                .last_tag(&pkg.id)
66	                .map(|t| t.version == cur_ver)
67	                .unwrap_or(false);
68	            (!tag_match, cur_ver)
69	        };
70	
71	        if is_release {
72	            let publishes_cargo = pkg
73	                .publish_to
74	                .iter()
75	                .any(|t| matches!(t, callisto_model::PublishTarget::CratesIo));
76	            let publishes_npm = pkg
77	                .publish_to
78	                .iter()
79	                .any(|t| matches!(t, callisto_model::PublishTarget::Npm { .. }));
80	            let is_platform_pkg = pkg
81	                .manifests
82	                .iter()
83	                .any(|m| matches!(m.role, callisto_model::ManifestRole::Platform { .. }));
84	
85	            if publishes_cargo {
86	                rust_crates.push(CratePublish {
87	                    name: pkg.id.name().to_string(),
88	                    version: ver.clone(),
89	                    publish_to: callisto_model::RegistryKey(
90	                        callisto_model::RegistryKey::CRATES_IO.to_string(),
91	                    ),
92	                    registry: None,
93	                });
94	            }
95	
96	            if publishes_npm {
97	                let tag = if ver.is_prerelease() {
98	                    Some("next".to_string())
99	                } else {
100	                    None
101	                };
102	
103	                if is_platform_pkg {
104	                    npm_platform_packages.push(callisto_model::NpmPublish {
105	                        name: pkg.id.name().to_string(),
106	                        version: ver.clone(),
107	                        publish_to: callisto_model::RegistryKey(
108	                            callisto_model::RegistryKey::NPM.to_string(),
109	                        ),
110	                        registry: None,
111	                        tag: tag.clone(),
112	                    });
113	                } else {
114	                    let platform_deps: Vec<String> = ws
115	                        .graph
116	                        .dependencies_of(&pkg.id)
117	                        .filter(|edge| {
118	                            ws.graph
119	                                .packages()
120	                                .find(|p| p.id == edge.to)
121	                                .map(|p| {
122	                                    p.manifests.iter().any(|m| {
123	                                        matches!(
124	                                            m.role,
125	                                            callisto_model::ManifestRole::Platform { .. }
126	                                        )
127	                                    })
128	                                })
129	                                .unwrap_or(false)
130	                        })
131	                        .map(|edge| edge.to.name().to_string())
132	                        .collect();
133	
134	                    npm_main_packages.push(NpmMainPublish {
135	                        name: pkg.id.name().to_string(),
136	                        version: ver.clone(),
137	                        publish_to: callisto_model::RegistryKey(
138	                            callisto_model::RegistryKey::NPM.to_string(),
139	                        ),
140	                        registry: None,
141	                        tag,
142	                        depends_on_platforms: platform_deps,
143	                    });
144	                }
145	            }
146	
147	            if !pkg.publish_to.is_empty()
148	                && !pkg.publish_to.iter().all(|t| *t == PublishTarget::None)
149	            {
150	                if let Some(ref sha) = head_sha {
151	                    releases.push(ReleaseEntry {
152	                        package: pkg.id.clone(),
153	                        tag_name: ws.tags.template(&pkg.id).render(&ver),
154	                        sha: sha.clone(),
155	                        changelog_section: None,
156	                    });
157	                }
158	            }
159	        }
160	    }
161	
162	    Ok(PublishPlan {
163	        schema_version: SCHEMA_VERSION,
164	        rust_crates,
165	        npm_main_packages,
166	        npm_platform_packages,
167	        releases,
168	        diagnostics: Vec::new(),
169	    })
170	}
