172	use callisto_model::{
173	    Ecosystem, PackageId, RateLimitPolicy, RegistryClient, RegistryError, TimeProvider, Version,
174	};
175	use std::time::Duration;
176	
177	pub struct PublishOrchestrator<R, P, T> {
178	    client: R,
179	    policy: P,
180	    time: T,
181	}
182	
183	impl<R, P, T> PublishOrchestrator<R, P, T>
184	where
185	    R: RegistryClient,
186	    P: RateLimitPolicy,
187	    T: TimeProvider,
188	{
189	    pub fn new(client: R, policy: P, time: T) -> Self {
190	        Self {
191	            client,
192	            policy,
193	            time,
194	        }
195	    }
196	
197	    pub fn parse_http_429_ttl(retry_after_header: &str) -> Option<Duration> {
198	        if let Ok(secs) = retry_after_header.parse::<u64>() {
199	            Some(Duration::from_secs(secs))
200	        } else {
201	            None
202	        }
203	    }
204	
205	    pub fn execute(&self, plan: &PublishPlan) -> Result<(), RegistryError> {
206	        for rust_crate in &plan.rust_crates {
207	            let pkg_id = PackageId::Prefixed {
208	                ecosystem: Ecosystem::Cargo,
209	                name: rust_crate.name.clone(),
210	            };
211	            self.publish_with_retry(&pkg_id, &rust_crate.version)?;
212	        }
213	
214	        for npm_pkg in &plan.npm_main_packages {
215	            let pkg_id = PackageId::Prefixed {
216	                ecosystem: Ecosystem::Npm,
217	                name: npm_pkg.name.clone(),
218	            };
219	            self.publish_with_retry(&pkg_id, &npm_pkg.version)?;
220	        }
221	
222	        for npm_pkg in &plan.npm_platform_packages {
223	            let pkg_id = PackageId::Prefixed {
224	                ecosystem: Ecosystem::Npm,
225	                name: npm_pkg.name.clone(),
226	            };
227	            self.publish_with_retry(&pkg_id, &npm_pkg.version)?;
228	        }
229	
230	        Ok(())
231	    }
232	
233	    fn publish_with_retry(
234	        &self,
235	        pkg_id: &PackageId,
236	        version: &Version,
237	    ) -> Result<(), RegistryError> {
238	        if self.client.is_published(pkg_id, version)? {
239	            return Ok(());
240	        }
241	
242	        loop {
243	            match self.client.publish(pkg_id, version) {
244	                Ok(_) => return Ok(()),
245	                Err(RegistryError::RateLimited(retry_after)) => {
246	                    if retry_after > Duration::from_secs(600) {
247	                        return Err(RegistryError::RateLimited(retry_after));
248	                    }
249	                    self.policy.check_rate_limit(retry_after)?;
250	                    self.time.sleep(retry_after);
251	                }
252	                Err(RegistryError::AuthFailed(err)) => {
253	                    return Err(RegistryError::AuthFailed(err));
254	                }
255	                Err(err) => {
256	                    return Err(err);
257	                }
258	            }
259	        }
260	    }
261	}
