131	    pub seed: &'a BTreeMap<PackageId, Severity>,
132	    pub reasons: &'a BTreeMap<PackageId, BumpReason>,
133	    pub named_by: &'a BTreeMap<PackageId, crate::aggregate::NamedBy>,
