344	fn bump_target<D: DependencyResolver>(
345	    id: &PackageId,
346	    sev: Severity,
347	    input: &CascadeInput<'_, D>,
348	) -> Result<Version, GraphError> {
349	    let base = input.base.get(id).cloned().ok_or_else(|| {
350	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
351	            path: PathBuf::from(id.name()),
352	            field: "version",
353	        })
354	    })?;
355	    let versioning = callisto_format::SemVerVersioning;
356	
357	    if let Some(pre) = input.pre {
358	        versioning
359	            .bump_prerelease(&base, sev, &pre.tag, &base)
360	            .map_err(GraphError::Bump)
361	    } else {
362	        versioning.bump(&base, sev).map_err(GraphError::Bump)
363	    }
364	}
