458	pub fn rewrite_spec(
459	    original: &DepSpec,
460	    new: &Version,
461	    eco: Ecosystem,
462	    cfg: &CascadeConfig,
463	) -> RewriteOutcome {
464	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm {
465	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
466	    }
467	
468	    if let Some(rewritten) = callisto_manifests::round_trip(eco, original, new) {
469	        RewriteOutcome::Rewritten(rewritten)
470	    } else {
471	        RewriteOutcome::LeftAlone(Diagnostic {
472	            code: DiagnosticCode::RangeNotRoundTrippable,
473	            severity: DiagnosticSeverity::Warning,
474	            message: format!(
475	                "spec `{}` could not be round-tripped toward version `{}`",
476	                original.render(),
477	                new.render()
478	            ),
479	            package: None,
480	            path: None,
481	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
482	            escalated_by: None,
483	        })
484	    }
