128	pub fn write_pre_json(state: &PreState) -> String {
129	    let mut map = IndexMap::new();
130	    map.insert(
131	        "mode".to_string(),
132	        serde_json::to_value(state.mode).unwrap(),
133	    );
134	    map.insert("tag".to_string(), serde_json::to_value(&state.tag).unwrap());
135	
136	    let mut init_map = IndexMap::new();
137	    for (pkg, ver) in &state.initial_versions {
138	        init_map.insert(pkg.clone(), serde_json::to_value(ver).unwrap());
139	    }
140	    map.insert(
141	        "initialVersions".to_string(),
142	        serde_json::to_value(init_map).unwrap(),
143	    );
144	    map.insert(
145	        "changesets".to_string(),
146	        serde_json::to_value(&state.changesets).unwrap(),
147	    );
148	
149	    let mut out = serde_json::to_string_pretty(&map).unwrap();
150	    out.push('\n');
151	    out
152	}
