136	                    }
137	                })
138	                .interact_text()
139	                .map_err(|e| CliError::Other(format!("Interactive prompt failed: {e}")))?;
140	            summary = Some(input_summary);
141	        }
142	
143	        // Step 5: Confirmation Preview
144	        let summary_text = summary.as_deref().unwrap_or("Updated package.");
145	        let temp_changeset = Changeset {
146	            entries: entries.clone(),
147	            summary: summary_text.to_string(),
148	        };
149	
150	        let preview_text = callisto_format::write_changeset(&temp_changeset)?;
151	        println!("\n=== Changeset Preview ===\n{preview_text}");
152	
153	        let confirm = Confirm::new()
154	            .with_prompt("Is this your desired changeset?")
155	            .default(true)
156	            .interact()
157	            .map_err(|e| CliError::Other(format!("Interactive confirmation failed: {e}")))?;
158	
159	        if !confirm {
160	            println!("Changeset creation cancelled.");
161	            return Ok(ExitCode::SUCCESS);
162	        }
163	    } else {
164	        return Err(CliError::NotATty);
165	    }
166	
167	    let raw_summary = summary.ok_or_else(|| {
168	        CliError::Other(
169	            "--summary is required when specifying packages via CLI flags in non-interactive mode"
170	                .to_string(),
171	        )
172	    })?;
173	    let summary_text = validate_summary(&raw_summary)?;
174	    let changeset = Changeset {
175	        entries,
