177	    };
178	    let text = callisto_format::write_changeset(&changeset)?;
179	
180	    let changeset_dir = ws.root.join(".changeset");
181	    let slug = generate_human_slug();
182	    let filename = format!("{slug}.md");
183	    let rel_path = format!(".changeset/{filename}");
184	
185	    let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
186	        // Compute what WOULD be written, but never touch disk.
187	        match global.format {
188	            OutputFormat::Json => {
189	                let env = json!({
190	                    "schemaVersion": SCHEMA_VERSION,
191	                    "command": "add",
192	                    "dryRun": true,
193	                    "path": rel_path,
194	                    "content": text
195	                });
196	                write_json(&mut std::io::stdout(), &env)?;
197	            }
198	            OutputFormat::Text => {
199	                println!("[DRY-RUN] Would add changeset: {rel_path} (no files written)\n\n{text}");
200	            }
201	        }
202	        return Ok(ExitCode::SUCCESS);
203	    };
204	
205	    let target_file = changeset_dir.join(&filename);
206	    fs::create_dir_all(&changeset_dir)?;
207	    callisto_manifests::atomic::atomic_write(&target_file, &text, &permit)?;
208	
209	    match global.format {
210	        OutputFormat::Json => {
211	            let env = json!({
212	                "schemaVersion": SCHEMA_VERSION,
213	                "command": "add",
214	                "path": rel_path
215	            });
216	            write_json(&mut std::io::stdout(), &env)?;
217	        }
218	        OutputFormat::Text => {
219	            log_line(global.format, &format!("Added changeset: {rel_path}"));
220	        }
221	    }
222	
223	    Ok(ExitCode::SUCCESS)
224	}
