229	fn validate_summary(summary: &str) -> Result<String, CliError> {
230	    let trimmed = summary.trim().to_string();
231	    if trimmed.is_empty() {
232	        return Err(CliError::Other(
233	            "--summary cannot be empty. Provide a non-empty description of the change.".to_string(),
234	        ));
235	    }
