47	/// Compiles `glob` into a [`globset::GlobMatcher`], surfacing a malformed
48	/// pattern as [`VcsError::InvalidGlob`] rather than letting it silently
49	/// disable filtering (which would match every tag -- see
50	/// `GitRepository::list_tags`'s own doc comment for why that's a real
51	/// correctness risk for release tagging).
52	fn compile_glob(glob: &str) -> Result<globset::GlobMatcher, VcsError> {
53	    globset::Glob::new(glob)
54	        .map(|g| g.compile_matcher())
55	        .map_err(|e| VcsError::InvalidGlob {
56	            pattern: glob.to_string(),
57	            message: e.to_string(),
58	        })
59	}
