61	impl GitDataSource for ShellGit<'_> {
62	    /// Always fetches the *full, unfiltered* tag list via `git tag --list`
63	    /// and applies `glob` (if any) locally with `globset` -- deliberately
64	    /// never delegates filtering to `git tag --list <pattern>`'s own
65	    /// (different) glob dialect. This is what guarantees byte-identical
66	    /// tag selection between this backend and the native `gix` path
67	    /// (`GitRepository::list_tags`, which also filters with `globset`)
68	    /// regardless of which one a caller ends up using.
69	    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
70	        let output = self.runner.run("git", &["tag", "--list"], &self.root)?;
71	        let all = output.stdout_lines().map(|s| s.to_string());
72	
73	        let matcher = glob.map(compile_glob).transpose()?;
74	
75	        Ok(all
76	            .filter(|t| matcher.as_ref().is_none_or(|m| m.is_match(t)))
77	            .map(TagName)
78	            .collect())
79	    }
