99	    /// Shells `git log --no-merges --format=<RECORD_SEP>%H<FIELD_SEP>%B
100	    /// <range> [-- <pathspecs>]`, matching the native path's shape
101	    /// field-for-field: `--no-merges` excludes merge commits exactly like
102	    /// `GitRepository::commits_since_with_pathspec`'s parent-count skip;
103	    /// `<since>..HEAD` (or bare `HEAD` for no bound) gives the same
104	    /// exclusive-lower-bound revision range as the revwalk's stop-at-
105	    /// `since` logic; and the trailing `-- <pathspecs>` reproduces `git
106	    /// log`'s own pathspec-prefix filtering.
107	    ///
108	    /// Deliberately does *not* pre-resolve `since_ref` via a separate
109	    /// `rev-parse` round-trip: an unresolvable `since_ref` already makes
110	    /// `git log <since_ref>..HEAD` itself fail (non-zero exit), which is
111	    /// surfaced below as `Err` exactly like any other `git log` failure --
112	    /// one shell call either way.
113	    fn commits_since(
114	        &self,
115	        since_ref: Option<&str>,
116	        pathspecs: &[PathBuf],
117	    ) -> Result<Vec<GitCommit>, VcsError> {
118	        let mut args: Vec<String> = vec![
119	            "log".to_string(),
120	            "--no-merges".to_string(),
121	            format!("--format={RECORD_SEP}%H{FIELD_SEP}%B"),
122	        ];
123	
124	        match since_ref {
125	            Some(r) => args.push(format!("{r}..HEAD")),
126	            None => args.push("HEAD".to_string()),
127	        }
128	
129	        if !pathspecs.is_empty() {
130	            args.push("--".to_string());
131	            args.extend(pathspecs.iter().map(|p| p.display().to_string()));
132	        }
133	
134	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
135	        let output = self.runner.run("git", &arg_refs, &self.root)?;
136	
137	        if !output.success() {
138	            return Err(VcsError::Git(format!(
139	                "`git log` failed in `{}`: {}",
140	                self.root.display(),
141	                output.stderr
142	            )));
143	        }
144	
145	        parse_git_log_output(&output.stdout, &self.root)
146	    }
