61	    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
62	        if let Some(repo) = &self.native {
63	            if let Ok(tags) = repo.list_tags(glob) {
64	                return Ok(tags);
65	            }
66	        }
67	        self.shell.list_tags(glob)
68	    }
