234	                        .map_err(|e| VersionParseError {
235	                            raw: raw.to_string(),
236	                            grammar,
237	                            message: e.to_string(),
238	                        })?;
239	                Ok(VersionReq {
240	                    grammar,
241	                    ecosystem,
242	                    req: ParsedVersionReq::Pep440(req),
243	                    raw: raw.to_string(),
244	                })
245	            }
246	            VersionGrammar::Maven => Err(VersionParseError {
247	                raw: raw.to_string(),
248	                grammar,
249	                message: format!("{grammar:?} version requirements not implemented"),
250	            }),
