263	        if self.grammar != v.grammar() {
264	            return Err(GrammarMismatch {
265	                left: self.grammar,
266	                right: v.grammar(),
267	            });
268	        }
269	        match (&self.req, &v.parsed) {
270	            (ParsedVersionReq::SemVer(req), ParsedVersion::SemVer(sv)) => Ok(req.matches(sv)),
271	            (ParsedVersionReq::Pep440(req), ParsedVersion::Pep440(pv)) => Ok(req.contains(pv)),
272	            _ => unreachable!(),
273	        }
274	    }
